H=W=18; axis=8
src = [[],[],[],[],[8,9],[6,7,8,9,10],[5,6,10],[5,6,9,10,11,12],[6,7,10],[7,8,9,10],[5,6,7,8,10,11,12],[],[],[],[],[],[],[]]
out=[[1]*W for _ in range(H)]
# shift off-axis pixels toward top and outward to their respective side edges
left=min(c for row in src for c in row if c<axis)
right=max(c for row in src for c in row if c>axis)
for r,cs in enumerate(src):
 for c in cs:
  if c==axis:
   out[r][c]=7
  elif c<axis:
   out[r-4][c-left]=7
  else:
   out[r-4][c+(W-1-right)]=7
# vertical beam through farthest aligned 7, retaining any 7 cells on axis
for r in range(0,11):
 if out[r][axis]!=7: out[r][axis]=2
print(''.join(str(x) for x in [left,right]))
for row in out: print(' '.join(map(str,row)))

out2=[[1]*18 for _ in range(18)]
for r,cs in enumerate(src):
 for c in cs:
  if c==8: out2[r][c]=7
  elif c<8: out2[r-5][c-5]=7
  else: out2[r-4][c+5]=7
for r in range(11):
 if out2[r][8]!=7: out2[r][8]=2
for row in out2: print(' '.join(map(str,row)))
